	if ( self::d( 'klausimas', $o ) ) { return false; }
	$src = array();
	foreach ( $o->get_items() as $it ) { if ( $it->get_meta( '_mnm_config' ) || $it->get_meta( '_mnm_container_size' ) || $it->get_meta( '_mnm_cart_key' ) ) { continue; } /* S1787: dėžutė — ne sandėlis */ $s = (string) $it->get_meta( '_ps_source' ); if ( ! $s ) { return false; } $src[ $s ] = 1; }
